	,updatePointerPos: function(snap) {
		if(snap == null) {
			snap = true;
		}
		var offX = 0;
		var offY = 0;
		if(!this.character.isPlayer) {
			offX = this.character.getMidpoint().x + 150 + this.character.cameraPosition[0];
			offY = this.character.getMidpoint().y - 100 + this.character.cameraPosition[1];
		} else {
			offX = this.character.getMidpoint().x - 100 - this.character.cameraPosition[0];
			offY = this.character.getMidpoint().y - 100 + this.character.cameraPosition[1];
		}
		this.cameraFollowPointer.setPosition(offX,offY);
		if(snap) {
			flixel_FlxG.camera.scroll.set_x(this.cameraFollowPointer.getMidpoint().x - flixel_FlxG.width / 2);
			flixel_FlxG.camera.scroll.set_y(this.cameraFollowPointer.getMidpoint().y - flixel_FlxG.height / 2);
		}
	}
	,updateHealthBar: function() {
		this.healthColorStepperR.set_value(this.character.healthColorArray[0]);
		this.healthColorStepperG.set_value(this.character.healthColorArray[1]);
		this.healthColorStepperB.set_value(this.character.healthColorArray[2]);
		var tmp = this.healthBar.backColorTransform;
		var tmp1 = this.healthBar.frontColorTransform;
		var Red = this.character.healthColorArray[0];
		var Green = this.character.healthColorArray[1];
		var Blue = this.character.healthColorArray[2];
		var color = flixel_util_FlxColor._new();
		var Alpha = 255;
		if(Alpha == null) {
			Alpha = 255;
		}
		color = ((Red > 255 ? 255 : Red < 0 ? 0 : Red) & 255) << 16 | ((Green > 255 ? 255 : Green < 0 ? 0 : Green) & 255) << 8 | (Blue > 255 ? 255 : Blue < 0 ? 0 : Blue) & 255 | ((Alpha > 255 ? 255 : Alpha < 0 ? 0 : Alpha) & 255) << 24;
		tmp.set_color(tmp1.set_color(color));
		this.healthIcon.changeIcon(this.character.healthIcon);
	}
