	,updateCharacterPositions: function() {
		var tmp;
		if(!(this.character != null && !this.character.isPlayer)) {
			if(this.character == null) {
				var name = this._char;
				tmp = name != "bf" && !StringTools.startsWith(name,"bf-") && !StringTools.endsWith(name,"-player") && !StringTools.endsWith(name,"-dead") || StringTools.endsWith(name,"-opponent") || StringTools.startsWith(name,"gf-") || StringTools.endsWith(name,"-gf") || name == "gf";
			} else {
				tmp = false;
			}
		} else {
			tmp = true;
		}
		if(tmp) {
			this.character.setPosition(this.dadPosition.x,this.dadPosition.y);
		} else {
			this.character.setPosition(this.bfPosition.x,this.bfPosition.y);
		}
		var fh = this.character;
		fh.set_x(fh.x + this.character.positionArray[0]);
		var fh = this.character;
		fh.set_y(fh.y + this.character.positionArray[1]);
	}
	,predictCharacterIsNotPlayer: function(name) {
		if(!(name != "bf" && !StringTools.startsWith(name,"bf-") && !StringTools.endsWith(name,"-player") && !StringTools.endsWith(name,"-dead") || StringTools.endsWith(name,"-opponent") || StringTools.startsWith(name,"gf-") || StringTools.endsWith(name,"-gf"))) {
			return name == "gf";
		} else {
			return true;
		}
	}
	,addAnimation: function(anim,name,fps,loop,indices) {
		if(!this.character.isAnimateAtlas) {
			if(indices != null && indices.length > 0) {
				this.character.animation.addByIndices(anim,name,indices,"",fps,loop);
			} else {
				this.character.animation.addByPrefix(anim,name,fps,loop);
			}
		} else if(indices != null && indices.length > 0) {
			this.character.atlas.anim.addBySymbolIndices(anim,name,indices,fps,loop);
		} else {
			this.character.atlas.anim.addBySymbol(anim,name,fps,loop);
		}
		if(!Object.prototype.hasOwnProperty.call(this.character.animOffsets.h,anim)) {
			this.character.addOffset(anim,0,0);
		}
	}
	,newAnim: function(anim,name) {
		return { offsets : [0,0], loop : false, fps : 24, anim : anim, indices : [], name : name};
	}
	,characterList: null
