	,findCorrectModData: function(data) {
		switch(data[modcharting_ModchartEditorState.EVENT_TYPE]) {
		case "ease":
			return data[modcharting_ModchartEditorState.EVENT_DATA][modcharting_ModchartEditorState.EVENT_EASEDATA];
		case "set":
			return data[modcharting_ModchartEditorState.EVENT_DATA][modcharting_ModchartEditorState.EVENT_SETDATA];
		}
		return null;
	}
	,setCorrectModData: function(data,dataStr) {
		switch(data[modcharting_ModchartEditorState.EVENT_TYPE]) {
		case "ease":
			data[modcharting_ModchartEditorState.EVENT_DATA][modcharting_ModchartEditorState.EVENT_EASEDATA] = dataStr;
			break;
		case "set":
			data[modcharting_ModchartEditorState.EVENT_DATA][modcharting_ModchartEditorState.EVENT_SETDATA] = dataStr;
			break;
		}
		return data;
	}
	,convertModData: function(data,newType) {
		switch(data[modcharting_ModchartEditorState.EVENT_TYPE]) {
		case "ease":
			if(newType == "set") {
				haxe_Log.trace("converting ease to set",{ fileName : "source/modcharting/ModchartEditorState.hx", lineNumber : 1563, className : "modcharting.ModchartEditorState", methodName : "convertModData"});
				var temp = [newType,[data[modcharting_ModchartEditorState.EVENT_DATA][modcharting_ModchartEditorState.EVENT_TIME],data[modcharting_ModchartEditorState.EVENT_DATA][modcharting_ModchartEditorState.EVENT_EASEDATA]],data[modcharting_ModchartEditorState.EVENT_REPEAT]];
				data = temp.slice();
			}
			break;
		case "set":
			if(newType == "ease") {
				haxe_Log.trace("converting set to ease",{ fileName : "source/modcharting/ModchartEditorState.hx", lineNumber : 1574, className : "modcharting.ModchartEditorState", methodName : "convertModData"});
				var temp = [newType,[data[modcharting_ModchartEditorState.EVENT_DATA][modcharting_ModchartEditorState.EVENT_TIME],1,"linear",data[modcharting_ModchartEditorState.EVENT_DATA][modcharting_ModchartEditorState.EVENT_SETDATA]],data[modcharting_ModchartEditorState.EVENT_REPEAT]];
				haxe_Log.trace(temp,{ fileName : "source/modcharting/ModchartEditorState.hx", lineNumber : 1580, className : "modcharting.ModchartEditorState", methodName : "convertModData"});
				data = temp.slice();
			}
			break;
		}
		return data;
	}
	,updateEventModData: function(shitToUpdate,isMod) {
		var data = this.getCurrentEventInData();
		if(data != null) {
			var dataStr = this.findCorrectModData(data);
			var dataSplit = dataStr.split(",");
			dataSplit[this.getEventModIndex() * 2 + (isMod ? 1 : 0)] = shitToUpdate;
			dataStr = this.stringifyEventModData(dataSplit);
			data = this.setCorrectModData(data,dataStr);
		}
	}
	,getEventModData: function(isMod) {
		var data = this.getCurrentEventInData();
		if(data != null) {
			var dataStr = this.findCorrectModData(data);
			var dataSplit = dataStr.split(",");
			return dataSplit[this.getEventModIndex() * 2 + (isMod ? 1 : 0)];
		}
		return "";
	}
	,stringifyEventModData: function(dataSplit) {
		var dataStr = "";
		var _g = 0;
		var _g1 = dataSplit.length;
		while(_g < _g1) {
			var i = _g++;
			dataStr += dataSplit[i];
			if(i < dataSplit.length - 1) {
				dataStr += ",";
			}
		}
		return dataStr;
	}
	,addNewModData: function() {
		var data = this.getCurrentEventInData();
		if(data != null) {
			var dataStr = this.findCorrectModData(data);
			dataStr += ",,";
			data = this.setCorrectModData(data,dataStr);
		}
		return data;
	}
	,removeModData: function() {
		var data = this.getCurrentEventInData();
		if(data != null) {
			if(this.selectedEventDataStepper.max > 0) {
				var dataStr = this.findCorrectModData(data);
				var dataSplit = dataStr.split(",");
				dataSplit.length -= 2;
				dataStr = this.stringifyEventModData(dataSplit);
				data = this.setCorrectModData(data,dataStr);
			}
		}
		return data;
	}
