	,getCurrentEventInData: function() {
		if(this.highlightedEvent == null) {
			return null;
		}
		var _g = 0;
		var _g1 = this.playfieldRenderer.modchart.data.events.length;
		while(_g < _g1) {
			var i = _g++;
			if(this.playfieldRenderer.modchart.data.events[i] == this.highlightedEvent) {
				return this.playfieldRenderer.modchart.data.events[i];
			}
		}
		return null;
	}
	,getMaxEventModDataLength: function() {
		var data = this.getCurrentEventInData();
		if(data != null) {
			var dataStr = this.findCorrectModData(data);
			var dataSplit = dataStr.split(",");
			return Math.floor(dataSplit.length / 2 - 1);
		}
		return 0;
	}
	,updateSelectedEventDataStepper: function() {
		this.selectedEventDataStepper.set_max(this.getMaxEventModDataLength());
		if(this.selectedEventDataStepper.value > this.selectedEventDataStepper.max) {
			this.selectedEventDataStepper.set_value(0);
		}
	}
	,updateStackedEventDataStepper: function() {
		this.stackedEventStepper.set_max(this.stackedHighlightedEvents.length - 1);
		this.stackedEventStepper.set_value(this.stackedEventStepper.max);
	}
	,getEventModIndex: function() {
		return Math.floor(this.selectedEventDataStepper.value);
	}
	,eventTypes: null
	,onSelectEvent: function(fromStackedEventStepper) {
		if(fromStackedEventStepper == null) {
			fromStackedEventStepper = false;
		}
		this.updateSelectedEventDataStepper();
		this.eventTimeStepper.set_value(parseFloat(this.highlightedEvent[modcharting_ModchartEditorState.EVENT_DATA][modcharting_ModchartEditorState.EVENT_TIME]));
		this.eventDataInputText.set_text(this.highlightedEvent[modcharting_ModchartEditorState.EVENT_DATA][modcharting_ModchartEditorState.EVENT_EASEDATA]);
		this.eventEaseInputText.set_alpha(0.5);
		this.eventTimeInputText.set_alpha(0.5);
		if(this.highlightedEvent[modcharting_ModchartEditorState.EVENT_TYPE] == "ease") {
			this.eventEaseInputText.set_alpha(1);
			this.eventTimeInputText.set_alpha(1);
			this.eventEaseInputText.set_text(this.highlightedEvent[modcharting_ModchartEditorState.EVENT_DATA][modcharting_ModchartEditorState.EVENT_EASE]);
			this.eventTimeInputText.set_text(this.highlightedEvent[modcharting_ModchartEditorState.EVENT_DATA][modcharting_ModchartEditorState.EVENT_EASETIME]);
		}
		this.eventTypeDropDown.set_selectedLabel(this.highlightedEvent[modcharting_ModchartEditorState.EVENT_TYPE]);
		this.eventModInputText.set_text(this.getEventModData(true));
		this.eventValueInputText.set_text(this.getEventModData(false));
		this.repeatBeatGapStepper.set_value(this.highlightedEvent[modcharting_ModchartEditorState.EVENT_REPEAT][modcharting_ModchartEditorState.EVENT_REPEATBEATGAP]);
		this.repeatCountStepper.set_value(this.highlightedEvent[modcharting_ModchartEditorState.EVENT_REPEAT][modcharting_ModchartEditorState.EVENT_REPEATCOUNT]);
		this.repeatCheckbox.set_checked(this.highlightedEvent[modcharting_ModchartEditorState.EVENT_REPEAT][modcharting_ModchartEditorState.EVENT_REPEATBOOL]);
		if(!fromStackedEventStepper) {
			this.stackedEventStepper.set_value(0);
		}
		this.dirtyUpdateEvents = true;
	}
	,getEvent: function(id,sender,data,params) {
		if(id == "change_numeric_stepper" && ((sender) instanceof flixel_addons_ui_FlxUINumericStepper)) {
			var nums = sender;
			var wname = nums.name;
			switch(wname) {
			case "repeatBeatGap":
				var data = this.getCurrentEventInData();
				if(data != null) {
					data[modcharting_ModchartEditorState.EVENT_REPEAT][modcharting_ModchartEditorState.EVENT_REPEATBEATGAP] = this.repeatBeatGapStepper.value;
					this.highlightedEvent = data;
					this.hasUnsavedChanges = true;
					this.dirtyUpdateEvents = true;
				}
				break;
			case "repeatCount":
				var data = this.getCurrentEventInData();
				if(data != null) {
					data[modcharting_ModchartEditorState.EVENT_REPEAT][modcharting_ModchartEditorState.EVENT_REPEATCOUNT] = this.repeatCountStepper.value;
					this.highlightedEvent = data;
					this.hasUnsavedChanges = true;
					this.dirtyUpdateEvents = true;
				}
				break;
			case "selectedEventMod":
				if(this.highlightedEvent != null) {
					this.eventDataInputText.set_text(this.highlightedEvent[modcharting_ModchartEditorState.EVENT_DATA][modcharting_ModchartEditorState.EVENT_EASEDATA]);
					this.eventModInputText.set_text(this.getEventModData(true));
					this.eventValueInputText.set_text(this.getEventModData(false));
				}
				break;
			case "stackedEvent":
				if(this.highlightedEvent != null) {
					this.highlightedEvent = this.stackedHighlightedEvents[this.stackedEventStepper.value | 0];
					this.onSelectEvent(true);
				}
				break;
			}
		}
	}
