var online_Glasshat = function() { };
$hxClasses["online.Glasshat"] = online_Glasshat;
online_Glasshat.__name__ = "online.Glasshat";
online_Glasshat.__properties__ = {get_connected:"get_connected"};
online_Glasshat.connected = null;
online_Glasshat.get_connected = function() {
	if(online_Glasshat.connectedToGame) {
		return online_Glasshat.loggedIn;
	} else {
		return false;
	}
};
online_Glasshat.initStuffs = function() {
	if(flixel_FlxG.save.data.doorsUsername == null) {
		return "no login found";
	}
	if(flixel_FlxG.save.data.doorsPassword == null) {
		return "no login found";
	}
	Main.popupManager.addPopup(new MessagePopup(5,"Glasshat Notification","Glasshat Online Disabled."));
	return "disabled";
};
online_Glasshat.test = function() {
};
online_Glasshat.syncAchievements = function() {
};
online_Glasshat.register = function() {
	flixel_addons_api_FlxGlasshat.registerUser(flixel_FlxG.save.data.doorsUsername,flixel_FlxG.save.data.doorsDisplayName,flixel_FlxG.save.data.doorsPassword,function(returnData) {
		if(returnData.Code == 200) {
			Main.popupManager.addPopup(new MessagePopup(5,"Glasshat Notification","Account successfully created!"));
			online_Glasshat.login();
		} else if(returnData.Code == 409) {
			Main.popupManager.addPopup(new MessagePopup(5,"Glasshat Notification","A user with the email " + Std.string(flixel_FlxG.save.data.doorsUsername) + " already exists... Try a new one!"));
		} else {
			Main.popupManager.addPopup(new MessagePopup(5,"Glasshat Notification","There seems to be an unknown error... Try again soon."));
		}
	});
};
online_Glasshat.login = function() {
	flixel_addons_api_FlxGlasshat.authUser(flixel_FlxG.save.data.doorsUsername,flixel_FlxG.save.data.doorsPassword,function(returnData) {
		online_Glasshat.loggedIn = returnData.Code == 200;
		if(online_Glasshat.loggedIn) {
			Main.popupManager.addPopup(new MessagePopup(5,"Glasshat Notification","Signed into Glasshat Online"));
		} else {
			Main.popupManager.addPopup(new MessagePopup(5,"Glasshat Notification","Couldn't sign in as " + Std.string(flixel_FlxG.save.data.doorsUsername)));
		}
	});
};
online_Glasshat.getScores = function(song,diff,limit,offset,callBack) {
	if(offset == null) {
		offset = 0;
	}
	if(limit == null) {
		limit = 100;
	}
	flixel_addons_api_FlxGlasshat.fetchScore(song,CoolUtil.defaultDifficulties[diff],limit,offset,callBack);
};
online_Glasshat.addScore = function(songname,diff,hash,acc,score,misses,mods) {
	flixel_addons_api_FlxGlasshat.addScore(songname,CoolUtil.defaultDifficulties[diff],hash,score,acc,misses,mods,function(returnData2) {
		if(returnData2.Code == "401") {
			Main.popupManager.addPopup(new MessagePopup(5,"Glasshat Notification","You need to log into Glasshat to publish your scores to the Leaderboards."));
			return;
		}
		if(returnData2.Code == "404") {
			Main.popupManager.addPopup(new MessagePopup(5,"Glasshat Notification","Score not uploaded. If you haven't modified game files, please report this issue."));
			return;
		}
		if(returnData2.Code == "406") {
			Main.popupManager.addPopup(new MessagePopup(5,"Glasshat Notification","This was not your high score... You can do better than that ! Good luck !"));
			return;
		}
		Main.popupManager.addPopup(new MessagePopup(5,"Glasshat Notification","Successfully uploaded your new highscore to Glasshat!"));
	},null,true);
};
