	,tryUnlockCategory: function(force) {
		if(force == null) {
			force = false;
		}
		if(this.get_isUnlocked()) {
			this.removePrerequisite();
			return { isUnlocked : true, success : true, catName : "none"};
		}
		if(DoorsUtil.knobs > this.catInfo.knobCost || force) {
			if(!force) {
				DoorsUtil.addKnobs(-this.catInfo.knobCost,1.0);
			}
			states_NewFreeplayState.instance.knobIndicator.addMoney(-this.catInfo.knobCost);
			backend_MenuSongManager.playSoundWithRandomPitch("GoldDecrease",[0.8,1.2],1.0);
			Reflect.setProperty(flixel_FlxG.save.data,this.catInfo.catName + "category-unlocked",true);
			flixel_FlxG.save.flush();
			states_NewFreeplayState.instance.isWatchingAnimation = true;
			backend_MenuSongManager.playSound("lockbreaksound",1.0);
			this.removePrerequisite(true,function() {
				states_NewFreeplayState.instance.isWatchingAnimation = false;
			});
			return { isUnlocked : false, success : true, catName : this.catInfo.catName};
		} else {
			backend_MenuSongManager.playSoundWithRandomPitch("lock",[0.8,1.2],1.0);
			return { isUnlocked : false, success : false, catName : "none"};
		}
	}
