		var Red = char1.healthColorArray[0];
		var Green = char1.healthColorArray[1];
		var Blue = char1.healthColorArray[2];
		var color = flixel_util_FlxColor._new();
		var Alpha = 255;
		if(Alpha == null) {
			Alpha = 255;
		}
		color = ((Red > 255 ? 255 : Red < 0 ? 0 : Red) & 255) << 16 | ((Green > 255 ? 255 : Green < 0 ? 0 : Green) & 255) << 8 | (Blue > 255 ? 255 : Blue < 0 ? 0 : Blue) & 255 | ((Alpha > 255 ? 255 : Alpha < 0 ? 0 : Alpha) & 255) << 24;
		tmp.set_color(color);
		var tmp = this.healthBar.frontColorTransform;
		var Red = char2.healthColorArray[0];
		var Green = char2.healthColorArray[1];
		var Blue = char2.healthColorArray[2];
		var color = flixel_util_FlxColor._new();
