	,clearNotesBefore: function(time) {
		var i = this.unspawnNotes.length - 1;
		while(i >= 0) {
			var daNote = this.unspawnNotes[i];
			if(daNote.strumTime - 350 < time) {
				daNote.set_active(false);
				daNote.set_visible(false);
				daNote.ignoreNote = true;
				this.invalidateNote(daNote);
			}
			--i;
		}
		i = this.notes.length - 1;
		while(i >= 0) {
			var daNote = this.notes.members[i];
			if(daNote.strumTime - 350 < time) {
				daNote.set_active(false);
				daNote.set_visible(false);
				daNote.ignoreNote = true;
				this.invalidateNote(daNote);
			}
			--i;
		}
	}
	,updateScore: function(miss) {
		if(miss == null) {
			miss = false;
		}
		var _gthis = this;
		this.scoreTxt.set_text("" + Std.string(backend_Lang.getText("score","generalshit")) + ": " + this.songScore + (" | " + Std.string(backend_Lang.getText("misses","generalshit")) + ": ") + this.songMisses + (" | " + Std.string(backend_Lang.getText("rating","generalshit")) + ": ") + this.ratingName + (this.ratingName != "?" ? " (" + Math.round(this.ratingPercent * 100 * 100) / 100 + "%) - " + this.ratingFC : ""));
		if(ClientPrefs.data.scoreZoom && !miss && !this.cpuControlled) {
			if(this.scoreTxtTween != null) {
				this.scoreTxtTween.cancel();
			}
			this.scoreTxt.scale.set_x(1.075);
			this.scoreTxt.scale.set_y(1.075);
			this.scoreTxtTween = flixel_tweens_FlxTween.tween(this.scoreTxt.scale,{ x : 1, y : 1},0.2,{ onComplete : function(twn) {
				_gthis.scoreTxtTween = null;
			}});
		}
	}
	,setSongTime: function(time) {
		if(time < 0) {
			time = 0;
		}
		flixel_FlxG.sound.music.pause();
		this.vocals.pause();
		flixel_FlxG.sound.music.set_time(time);
		flixel_FlxG.sound.music.set_pitch(this.playbackRate);
		flixel_FlxG.sound.music.play();
		if(Conductor.songPosition <= this.vocals._length) {
			this.vocals.set_time(time);
			this.vocals.set_pitch(this.playbackRate);
		}
		this.vocals.play();
		Conductor.songPosition = time;
		this.songTime = time;
	}
	,previousFrameTime: null
	,lastReportedPlayheadPosition: null
	,songTime: null
	,startSong: function() {
		this.startingSong = false;
		this.previousFrameTime = flixel_FlxG.game.ticks;
		this.lastReportedPlayheadPosition = 0;
		flixel_FlxG.sound.playMusic("songs:assets/songs/" + StringTools.replace(states_PlayState.SONG.song.toLowerCase()," ","-") + "/Inst." + "mp3",1,false);
		flixel_FlxG.sound.music.set_pitch(this.playbackRate);
		var _g = this;
		var tmp = function() {
			_g.finishSong();
		};
		flixel_FlxG.sound.music.onComplete = tmp;
		this.vocals.play();
		if(states_PlayState.startOnTime > 0) {
			this.setSongTime(states_PlayState.startOnTime - 500);
		}
		states_PlayState.startOnTime = 0;
		if(this.paused) {
			flixel_FlxG.sound.music.pause();
			this.vocals.pause();
		}
		this.songLength = flixel_FlxG.sound.music._length;
		flixel_tweens_FlxTween.tween(this.timeBar,{ alpha : 1},0.5,{ ease : flixel_tweens_FlxEase.circOut});
		flixel_tweens_FlxTween.tween(this.timeTxt,{ alpha : 1},0.5,{ ease : flixel_tweens_FlxEase.circOut});
		if(this.hasFakeTimerArray.indexOf(states_PlayState.SONG.song.toLowerCase()) != -1) {
			this.hasFakeTimer = true;
			this.songLengthFake = this.getFakeTime(states_PlayState.SONG.song.toLowerCase());
		}
	}
