	,eventPushed: function(event) {
		this.stagesFunc(function(stage) {
			stage.eventPushed(event);
		});
		switch(event.event) {
		case "Change Character":
			var charType = 0;
			switch(event.value1.toLowerCase()) {
			case "gf":case "girlfriend":
				charType = 2;
				break;
			case "dad":case "opponent":
				charType = 1;
				break;
			case "mom":case "opponent2":
				charType = 3;
				break;
			default:
				charType = 0;
			}
			var newCharacter = event.value2;
			this.addCharacterToList(newCharacter,charType);
			break;
		case "Chromatic Aberrate":
			if(!ClientPrefs.data.shaders) {
				return;
			}
			if(this.chromaticEvent == null) {
				this.chromaticEvent = new shaders_ChromaticAberration();
				this.chromaticEvent.set_iOffset(0);
				this.add(this.chromaticEvent);
				var filter = new openfl_filters_ShaderFilter(this.chromaticEvent.shader);
				this.camGameFilters.push(filter);
				this.camHUDFilters.push(filter);
				this.updateCameraFilters("camGame");
				this.updateCameraFilters("camHUD");
				this.hasChromaticAberration = true;
				var x = 0;
				var y = 0;
				if(y == null) {
					y = 0;
				}
				if(x == null) {
					x = 0;
				}
				this.chromaticPoint = new flixel_math_FlxBasePoint(x,y);
			}
			break;
		case "Pixelated Effect":
			if(!ClientPrefs.data.shaders) {
				return;
			}
			if(!this.hasPixel) {
				this.pixelEvent = new shaders_MosaicShader();
				this.pixelEvent.strength = 0;
				this.add(this.pixelEvent);
				this.scanlineEvent = new shaders_ScanlineShader();
				this.scanlineEvent.strength = 0;
				this.scanlineEvent.pixelsBetweenEachLine = 15.0;
				this.scanlineEvent.smooth = false;
				this.add(this.scanlineEvent);
				var filter = new openfl_filters_ShaderFilter(this.pixelEvent.shader);
				this.camGameFilters.push(filter);
				this.camHUDFilters.push(filter);
				filter = new openfl_filters_ShaderFilter(this.scanlineEvent.shader);
				this.camGameFilters.push(filter);
				this.camHUDFilters.push(filter);
				this.updateCameraFilters("camGame");
				this.updateCameraFilters("camHUD");
				this.hasPixel = true;
				var x = 0;
				var y = 0;
				if(y == null) {
					y = 0;
				}
				if(x == null) {
					x = 0;
				}
				this.pixelPoint = new flixel_math_FlxBasePoint(x,y);
				var x = 0;
				var y = 0;
				if(y == null) {
					y = 0;
				}
				if(x == null) {
					x = 0;
				}
				this.scanlinePoint = new flixel_math_FlxBasePoint(x,y);
			}
			break;
		case "spawn credits":
			this.manuallySpawnCredits = true;
			break;
		case "spawn lyrics":
			if(event.value1 == "true" || event.value1 == "") {
				this.lyrics.push(backend_Lang.getText(StringTools.replace(event.value2," ","_"),"lyrics/" + states_PlayState.SONG.song.toLowerCase()));
				haxe_Log.trace("" + StringTools.replace(event.value2," ","_") + " | " + ("lyrics/" + states_PlayState.SONG.song.toLowerCase()),{ fileName : "source/states/PlayState.hx", lineNumber : 2970, className : "states.PlayState", methodName : "eventPushed"});
			} else {
				this.lyrics.push(event.value2);
			}
			break;
		case "timCum":
			if(!Object.prototype.hasOwnProperty.call(this.eventPushedMap.h,event.event)) {
				new states_mechanics_TimothyCum();
			}
			break;
		}
		if(!Object.prototype.hasOwnProperty.call(this.eventPushedMap.h,event.event)) {
			this.eventPushedMap.h[event.event] = true;
		}
	}
	,eventNoteEarlyTrigger: function(event) {
		switch(event.event) {
		case "bfStartThrowMic":
			return 700;
		case "bfThrowMic":
			return 200;
		case "db-figureSpawn":
			return 1501;
		case "screechHit":
			return 273;
		case "seekDodge":
			return Conductor.crochet * Math.round(Conductor.bpm / 37.5);
		case "spawnEyes":
			return 1042;
		case "spawnSeek":
			return 3084;
		case "timCum":
			return 500;
		}
		return 0;
	}
	,sortByShit: function(Obj1,Obj2) {
		var Value1 = Obj1.strumTime;
		var Value2 = Obj2.strumTime;
		var result = 0;
		if(Value1 < Value2) {
			result = -1;
		} else if(Value1 > Value2) {
			result = 1;
		}
		return result;
	}
	,sortByTime: function(Obj1,Obj2) {
		var Value1 = Obj1.strumTime;
		var Value2 = Obj2.strumTime;
		var result = 0;
		if(Value1 < Value2) {
			result = -1;
		} else if(Value1 > Value2) {
			result = 1;
		}
		return result;
	}
	,skipArrowStartTween: null
	,generateStaticArrows: function(player,generateHeartbeat) {
		if(generateHeartbeat == null) {
			generateHeartbeat = false;
		}
		var path = states_PlayState.SONG.song;
		var invalidChars = new EReg("[~&\\\\;:<>#]","");
		var hideChars = new EReg("[.,'\"%?!]","");
		var path1 = invalidChars.split(StringTools.replace(path," ","-")).join("-");
		var songName = hideChars.split(path1).join("").toLowerCase();
		songName = songName.toLowerCase();
		if(!generateHeartbeat) {
			var _g = 0;
			while(_g < 4) {
				var i = _g++;
				var targetAlpha = 1;
				if(player < 1) {
					switch(states_PlayState.SONG.song) {
					case "404":case "left-behind":case "left-behind-hell":
						break;
					default:
						if(!DoorsUtil.modifierActive(61) && ModifierManager.isModifierApplicable(61,states_PlayState.SONG.song)) {
							if(!ClientPrefs.data.opponentStrums) {
								targetAlpha = 0;
							} else if(ClientPrefs.data.middleScroll) {
								targetAlpha = 0.35;
							}
						}
					}
				}
				var babyArrow;
				switch(states_PlayState.SONG.song) {
				case "404":case "left-behind":case "left-behind-hell":
					babyArrow = new objects_StrumNote(states_PlayState.STRUM_X,this.strumLine.y,i,player,-1);
					break;
				default:
					if(!DoorsUtil.modifierActive(61) && ModifierManager.isModifierApplicable(61,states_PlayState.SONG.song)) {
						babyArrow = new objects_StrumNote(ClientPrefs.data.middleScroll ? states_PlayState.STRUM_X_MIDDLESCROLL : states_PlayState.STRUM_X,this.strumLine.y,i,player,-1);
					} else {
						babyArrow = new objects_StrumNote(states_PlayState.STRUM_X,this.strumLine.y,i,player,-1);
					}
				}
				babyArrow.downScroll = ClientPrefs.data.downScroll;
				if(!this.skipArrowStartTween) {
					if(["404","left-behind","left-behind-hell"].indexOf(states_PlayState.SONG.song) == -1 && !DoorsUtil.modifierActive(61) && ModifierManager.isModifierApplicable(61,states_PlayState.SONG.song)) {
						babyArrow.set_y(babyArrow.y + 300);
						flixel_tweens_FlxTween.tween(babyArrow,{ y : babyArrow.y - 300},1,{ ease : flixel_tweens_FlxEase.circOut, startDelay : 0.5 + 0.2 * i});
					}
					babyArrow.set_alpha(0);
					flixel_tweens_FlxTween.tween(babyArrow,{ alpha : targetAlpha},1,{ ease : flixel_tweens_FlxEase.circOut, startDelay : 0.5 + 0.2 * i});
				} else {
					babyArrow.strumSprite.set_alpha(targetAlpha);
				}
				if(player == 1) {
					this.playerStrums.add(babyArrow);
				} else {
					var songBased = this.setStrumPositionsFromName(songName);
					if(songBased != 0) {
						babyArrow.set_x(songBased);
					}
					switch(states_PlayState.SONG.song) {
					case "404":case "left-behind":case "left-behind-hell":
						break;
					default:
						if(!DoorsUtil.modifierActive(61) && ModifierManager.isModifierApplicable(61,states_PlayState.SONG.song)) {
							if(ClientPrefs.data.middleScroll) {
								babyArrow.set_x(babyArrow.x + 310);
								if(i > 1) {
									babyArrow.set_x(babyArrow.x + (flixel_FlxG.width / 2 + 25));
								}
							}
						}
					}
					this.opponentStrums.add(babyArrow);
				}
				this.strumLineNotes.add(babyArrow);
				babyArrow.postAddedToGroup();
			}
		} else {
			var babyArrow = new objects_StrumNote(states_PlayState.STRUM_X_MIDDLESCROLL,this.strumLine.y,4,1,-1);
			babyArrow.downScroll = true;
			babyArrow.strumSprite.set_alpha(1);
			this.playerStrums.add(babyArrow);
			this.strumLineNotes.add(babyArrow);
			babyArrow.postAddedToGroup();
			var babyArrow = new objects_StrumNote(states_PlayState.STRUM_X_MIDDLESCROLL,this.strumLine.y,5,1,-1);
			babyArrow.downScroll = true;
			babyArrow.strumSprite.set_alpha(1);
			this.playerStrums.add(babyArrow);
			this.strumLineNotes.add(babyArrow);
			babyArrow.postAddedToGroup();
		}
	}
