	,musicThing: function() {
		if(DoorsUtil.isDead) {
			return;
		}
		if(this.isDark && this.bossState == "None") {
			if(DoorsUtil.isDead) {
				return;
			}
			backend_MenuSongManager.crossfade("DarkAmbience",0.3,120,true);
			return;
		}
		if(this.room.musicData != null) {
			backend_MenuSongManager.crossfade(DoorsUtil.handleMusicVariations(this.room.musicData),1,this.room.musicData.bpm,true);
			return;
		}
		switch(this.bossState) {
		case "None":
			backend_MenuSongManager.crossfade("storyModeBGM",1,93,true);
			break;
		case "courtyard":
			backend_MenuSongManager.crossfade("courtyard",1,110,true);
			break;
		case "figure1":case "figure2":
			backend_MenuSongManager.crossfade("storyModeBoss",1,120,true);
			break;
		case "greenhouse":
			backend_MenuSongManager.crossfade("greenhouse",1,80,true);
			break;
		case "lobby":
			backend_MenuSongManager.crossfade("storyModeIntro",1,93,true);
			break;
		case "pre-run":
			backend_MenuSongManager.crossfade("storyModePre",1,120,true);
			break;
		case "puzzle-paintings":
			backend_MenuSongManager.crossfade("storyModePaintings",1,100,true);
			break;
		case "seek1":case "seek2":
			backend_MenuSongManager.crossfade("storyModeBoss",1,120,true);
			break;
		}
		if(this.bossState == "None") {
			if(this.room.room.roomType == "Greenhouse") {
				backend_MenuSongManager.crossfade("greenhouse",1,80,true);
			}
		}
	}
