	,overlapCounter: null
	,placeFurniture: function(x) {
		this.nextFurniture.set_x(x);
		this.overlapCounter = 0;
		if(x % 2048 > 580 && x % 2048 < 1496) {
			return false;
		}
		var _g = 0;
		var _g1 = this.bgFurnitureGroup.group.members;
		while(_g < _g1.length) {
			var spr = _g1[_g];
			++_g;
			if(this.nextFurniture.overlaps(spr)) {
				this.overlapCounter += 1;
			}
		}
		this.nextFurniture.loadGraphic(Paths.image(StringTools.replace(this.nextFurniturePath,"Left",this.getClosestLightSource(x,this.nextFurniture.get_width()))));
		this.nextFurniture.set_antialiasing(ClientPrefs.get_globalAntialiasing());
		if(this.overlapCounter == 0) {
			this.push(this.nextFurniture,!this.nextForeground);
			return true;
		}
		return false;
	}
	,push: function(spr,isBackground) {
		if(isBackground == null) {
			isBackground = true;
		}
		if(isBackground) {
			this.bgFurnitureGroup.add(spr);
		} else {
			this.fgFurnitureGroup.add(spr);
		}
	}
	,getClosestLightSource: function(x,objWidth) {
		var lightSource1 = 650 - this.wall.x * 2048;
		var lightSource2 = 650 - this.wall.x * 2048;
		var objCenter = x + objWidth / 2;
		var distance1 = Math.abs(lightSource1 - objCenter % 2048);
		var distance2 = Math.abs(lightSource2 - objCenter % 2048);
		if(distance1 < distance2) {
			return "Left";
		} else {
			return "Right";
		}
	}
