	,eventCalled: function(eventName,value1,value2,flValue1,flValue2,strumTime) {
		switch(eventName) {
		case "Change Character":
			if(value2 == "madseek") {
				this.seek_legs.set_visible(false);
			} else if(value2 == "seek_run_body") {
				this.seek_legs.set_visible(true);
			}
			break;
		case "seekDodge":
			this.spawnNewDodgeRoom();
			break;
		case "seekEndSong":
			var killYourself = value1.split(";");
			var duration = 0.6;
			var ease = "sineInOut";
			if(killYourself.length >= 1) {
				duration = parseFloat(killYourself[0]);
			}
			if(killYourself.length >= 2) {
				ease = killYourself[1];
			}
			if(value2 == "True") {
				flixel_tweens_FlxTween.tween(this.seek_legs,{ x : this.seek_legs.x + 2000},duration,{ ease : states_PlayState.instance.getFlxEaseByString(ease)});
				flixel_tweens_FlxTween.tween(this.game.songCharacterGroups[2],{ x : this.game.songCharacterGroups[2].x + 2000},duration,{ ease : states_PlayState.instance.getFlxEaseByString(ease)});
			} else {
				flixel_tweens_FlxTween.tween(this.seek_legs,{ x : this.seek_legs.x - 2000},duration,{ ease : states_PlayState.instance.getFlxEaseByString(ease)});
				flixel_tweens_FlxTween.tween(this.game.songCharacterGroups[2],{ x : this.game.songCharacterGroups[2].x - 2000},duration,{ ease : states_PlayState.instance.getFlxEaseByString(ease)});
			}
			break;
		case "seekTweenIntoPlace":
			flixel_tweens_FlxTween.tween(this.game.songCharacters[2],{ x : 450},Conductor.crochet / 1000 * (flValue2 * 2),{ ease : flixel_tweens_FlxEase.expoOut});
			break;
		case "spawnSeek":
			this.spawnIdleSeek();
			break;
		case "spawnSeekHand":
			this.spawnSeekHand(flValue1,value2);
			break;
		case "toggleSeekPov":
			if(this.isPov) {
				var fh = states_PlayState.instance.dadGroup;
				fh.set_x(fh.x - 300);
				this.theBigRed.set_alpha(0);
				this.theRedStatic.set_alpha(0);
				this.game.camGame.fade(3605760,5,true,null,true);
				states_PlayState.instance.timeBar.set_alpha(1);
				states_PlayState.instance.timeBar.frontColorTransform.alphaMultiplier = 1;
				states_PlayState.instance.timeBar.backColorTransform.alphaMultiplier = 0.00001;
				states_PlayState.instance.timeTxt.set_alpha(1);
				states_PlayState.instance.scoreTxt.set_alpha(1);
				states_PlayState.instance.healthBar.set_alpha(1);
				states_PlayState.instance.healthBar.frontColorTransform.alphaMultiplier = 1;
				states_PlayState.instance.healthBar.backColorTransform.alphaMultiplier = 1;
				states_PlayState.instance.iconP1.set_alpha(1);
				states_PlayState.instance.iconP2.set_alpha(1);
				this.fgFurnitureGroup.set_visible(true);
			} else {
				var fh = states_PlayState.instance.dadGroup;
				fh.set_x(fh.x + 300);
				this.theBigRed.set_alpha(0.4);
				this.theRedStatic.set_alpha(1);
				this.game.camGame.fade(3605760,5,true,null,true);
				states_PlayState.instance.timeBar.set_alpha(0.000001);
				states_PlayState.instance.timeBar.frontColorTransform.alphaMultiplier = 0.00001;
				states_PlayState.instance.timeBar.backColorTransform.alphaMultiplier = 0.00001;
				states_PlayState.instance.timeTxt.set_alpha(0.000001);
				states_PlayState.instance.scoreTxt.set_alpha(0.000001);
				states_PlayState.instance.healthBar.set_alpha(0.000001);
				states_PlayState.instance.healthBar.frontColorTransform.alphaMultiplier = 0.00001;
				states_PlayState.instance.healthBar.backColorTransform.alphaMultiplier = 0.00001;
				states_PlayState.instance.iconP1.set_alpha(0.000001);
				states_PlayState.instance.iconP2.set_alpha(0.000001);
				this.fgFurnitureGroup.set_visible(false);
			}
			this.isPov = !this.isPov;
			break;
		}
	}
