	,update: function(elapsed) {
		var lerpVal = Math.max(0,Math.min(1,elapsed * 8));
		var a = this.bobsBookOutline.alpha;
		this.bobsBookOutline.set_alpha(a + lerpVal / 4 * (0.0001 - a));
	}
	,beatHit: function(curBeat) {
		this.boombox.onBeatHit(curBeat);
		if(curBeat % 4 == 0) {
			this.bobsBookOutline.set_alpha(0.4);
		}
	}
	,onHandleFurniture: function(furSprite,furName,side,specificAttributes,elapsed) {
		switch(furName) {
		case "bell":
			if(furSprite.isHovered) {
				if(flixel_FlxG.mouse._leftButton.current == 2) {
					AwardsManager.anyoneHome = true;
				}
			}
			break;
		case "bobsBook":
			if(furSprite.isHovered) {
				if(furSprite.justHovered) {
					furSprite.loadGraphic(Paths.image("story_mode_backgrounds/lobby/bobsBookOutline"));
				}
				if(flixel_FlxG.mouse._leftButton.current == 2) {
					states_StoryMenuState.instance.theMouse.startLongAction(0.5,function() {
						states_StoryMenuState.instance.persistentUpdate = false;
						states_StoryMenuState.instance.openSubState(new substates_story_BobsBookSubState());
					});
				}
			} else if(furSprite.justStoppedHovering) {
				furSprite.loadGraphic(Paths.image("story_mode_backgrounds/lobby/bobsBook"));
			}
			break;
		}
	}
