	,chooseSong: function() {
		states_PlayState.isStoryMode = false;
		states_PlayState.storyDifficulty = CoolUtil.defaultDifficulties.indexOf(CoolUtil.difficulties[this.curDifficulty]);
		var songLowercase = this.metadatas[this.curSelection].internalName.toLowerCase();
		var poop = Highscore.formatSong(songLowercase,this.curDifficulty);
		if(states_NewFreeplayState.currentCategory == "freeplay") {
			poop = Highscore.formatSong(songLowercase,1);
		}
		states_PlayState.SONG = Song.loadFromJson(poop,songLowercase);
		var _this = flixel_FlxG.keys.pressed;
		if(_this.keyManager.checkStatusUnsafe(16,_this.status)) {
			states_MusicBeatState.switchState(states_LoadingState.getNextState(new editors_ChartingState(),false));
		} else {
			states_MusicBeatState.switchState(states_LoadingState.getNextState(new states_PlayState(),false));
		}
		return true;
	}
