substates_PauseSubState.restartSong = function(noTrans) {
	if(noTrans == null) {
		noTrans = false;
	}
	states_PlayState.instance.paused = true;
	if(states_PlayState.isStoryMode) {
		DoorsUtil.curRun.revivesLeft -= 1;
		DoorsUtil.saveRunData();
	}
	states_MusicBeatState.resetState();
};
substates_PauseSubState.performQuit = function() {
	if(DoorsUtil.curRun.revivesLeft > 0 || !states_PlayState.isStoryMode) {
		states_PlayState.deathCounter = 0;
		states_PlayState.seenCutscene = false;
		if(states_PlayState.isStoryMode) {
			DoorsUtil.curRun.revivesLeft -= 1;
			DoorsUtil.curRun.latestHealth = Math.max(1,states_PlayState.instance.health);
			DoorsUtil.saveRunData();
		}
		backend_MenuSongManager.curMusic = "";
		if(states_PlayState.isStoryMode) {
			states_MusicBeatState.switchState(new states_StoryMenuState());
		} else {
			states_MusicBeatState.switchState(new states_NewFreeplayState());
		}
		states_PlayState.cancelMusicFadeTween();
		states_PlayState.changedDifficulty = false;
		states_PlayState.chartingMode = false;
	} else {
		states_PlayState.deathCounter = 0;
		states_PlayState.seenCutscene = false;
		states_StoryMenuState.resetData();
		if(states_PlayState.isStoryMode) {
			states_MusicBeatState.switchState(new states_StoryMenuState());
		}
		states_PlayState.cancelMusicFadeTween();
		states_PlayState.changedDifficulty = false;
		states_PlayState.chartingMode = false;
	}
};
